const WORKFLOW_NAMES = {}; // optional: { '<workflowId>': 'Customer Feedback Intelligence', ... }

const executions = $input.all().flatMap((item) => (Array.isArray(item.json.data) ? item.json.data : []));
if (executions.length === 0) return SAMPLE.map((json) => ({ json }));

const rows = {};
for (const e of executions) {
  const workflow = WORKFLOW_NAMES[e.workflowId] ?? String(e.workflowId);
  const date = String(e.startedAt).slice(0, 10);
  const r = (rows[`${workflow}|${date}`] ??= { workflow, date, runs: 0, failures: 0, duration_total_s: 0, items_processed: 0, llm_tokens: 0 });
  r.runs++;
  if (e.status === 'error' || e.status === 'crashed') r.failures++;
  if (e.stoppedAt) r.duration_total_s += (new Date(e.stoppedAt) - new Date(e.startedAt)) / 1000;
  r.items_processed++; // one business item per execution unless your workflows log item counts
}
return Object.values(rows).map(({ duration_total_s, ...r }) => ({
  json: { ...r, avg_duration_s: Math.round((duration_total_s / r.runs) * 10) / 10 },
}));

const CONFIG = {
  success_rate_slo: 0.95,
  latency_z_threshold: 2,
  volume_drop_ratio: 0.5,
  baseline_days: 7,
  // ASSUMPTION: minutes a person needed per item before automation. Validate with the team before reporting.
  manual_minutes_per_item: {
    'Customer Feedback Intelligence': 4,
    'Business Process Issue Triage': 12,
    'Requirement Validation Gate': 20,
    'Meeting Transcript to Backlog': 30,
  },
  default_manual_minutes: 5,
  // ASSUMPTION: blended LLM price in EUR per 1M tokens. Set it from your model and contract.
  llm_eur_per_million_tokens: 0.5,
};

const mean = (a) => (a.length ? a.reduce((s, x) => s + x, 0) / a.length : 0);
const std = (a) => {
  const m = mean(a);
  return Math.sqrt(mean(a.map((x) => (x - m) ** 2)));
};
const round = (x, d = 2) => Math.round(x * 10 ** d) / 10 ** d;
const successRate = (r) => (r.runs ? (r.runs - r.failures) / r.runs : 1);

const byWorkflow = {};
for (const { json } of $input.all()) (byWorkflow[json.workflow] ??= []).push(json);

const kpis = [];
const anomalies = [];
for (const [workflow, rows] of Object.entries(byWorkflow)) {
  rows.sort((a, b) => a.date.localeCompare(b.date));
  const current = rows[rows.length - 1];
  const baseline = rows.slice(-1 - CONFIG.baseline_days, -1);
  const currentSr = successRate(current);
  const baselineSr = baseline.length ? mean(baseline.map(successRate)) : currentSr;
  const durations = baseline.map((r) => r.avg_duration_s);
  const durationMean = mean(durations);
  const durationStd = Math.max(std(durations), 0.1 * durationMean, 0.01);
  const latencyZ = baseline.length ? (current.avg_duration_s - durationMean) / durationStd : 0;
  const baselineVolume = mean(baseline.map((r) => r.items_processed));
  const last7 = rows.slice(-7);
  const items7 = last7.reduce((s, r) => s + r.items_processed, 0);
  const tokens7 = last7.reduce((s, r) => s + (r.llm_tokens || 0), 0);
  const minutes = CONFIG.manual_minutes_per_item[workflow] ?? CONFIG.default_manual_minutes;

  kpis.push({
    workflow,
    date: current.date,
    runs: current.runs,
    failures: current.failures,
    success_rate: round(currentSr, 3),
    baseline_success_rate: round(baselineSr, 3),
    avg_duration_s: current.avg_duration_s,
    baseline_avg_duration_s: round(durationMean, 1),
    latency_z: round(latencyZ),
    items_processed: current.items_processed,
    items_last_7d: items7,
    hours_saved_last_7d: round((items7 * minutes) / 60, 1),
    llm_cost_eur_last_7d: round((tokens7 / 1e6) * CONFIG.llm_eur_per_million_tokens),
  });

  if (currentSr < CONFIG.success_rate_slo) {
    anomalies.push({ workflow, type: 'success_rate_breach', detail: `success rate ${round(currentSr * 100, 1)}% vs SLO ${CONFIG.success_rate_slo * 100}% (baseline ${round(baselineSr * 100, 1)}%)` });
  }
  if (latencyZ > CONFIG.latency_z_threshold) {
    anomalies.push({ workflow, type: 'latency_spike', detail: `avg duration ${current.avg_duration_s}s vs baseline ${round(durationMean, 1)}s (z=${round(latencyZ, 1)})` });
  }
  if (baselineVolume > 0 && current.items_processed < CONFIG.volume_drop_ratio * baselineVolume) {
    anomalies.push({ workflow, type: 'volume_drop', detail: `${current.items_processed} items vs baseline ${round(baselineVolume, 1)}` });
  }
}

const totals = {
  items_last_7d: kpis.reduce((s, k) => s + k.items_last_7d, 0),
  hours_saved_last_7d: round(kpis.reduce((s, k) => s + k.hours_saved_last_7d, 0), 1),
  llm_cost_eur_last_7d: round(kpis.reduce((s, k) => s + k.llm_cost_eur_last_7d, 0)),
};

return [{
  json: {
    generated_at: new Date().toISOString(),
    has_anomalies: anomalies.length > 0,
    anomalies,
    kpis,
    totals,
    // Pre-rendered text for the LLM prompt, so no raw JSON (and no braces) reaches the model.
    anomalies_text: anomalies.map((a) => `- ${a.workflow}: ${a.type} (${a.detail})`).join('\n') || '- none',
    kpi_text: kpis.map((k) => `- ${k.workflow}: ${k.runs} runs, ${k.failures} failed, ${k.avg_duration_s}s avg, ${k.items_last_7d} items / ${k.hours_saved_last_7d} h saved / EUR ${k.llm_cost_eur_last_7d} LLM cost in 7d`).join('\n'),
  },
}];

