// One row per workflow per day for the KPI history sheet (trend charts, monthly reporting).
const { generated_at, kpis, anomalies } = $input.first().json;
return kpis.map((k) => ({
  json: { ...k, generated_at, anomalies: anomalies.filter((a) => a.workflow === k.workflow).map((a) => a.type).join(', ') },
}));
